message.content:
以下是可用的所有函式列表：

```json
{
  "activateParkingBrake": {
    "description": "Activates the parking brake of the vehicle.",
    "parameters": {
      "mode": {
        "type": "string",
        "enum": ["engage", "release"],
        "description": "The mode to set."
      }
    }
  },
  "adjustClimateControl": {
    "description": "Adjusts the climate control of the vehicle.",
    "parameters": {
      "temperature": {
        "type": "number",
        "description": "The temperature to set in degree. Default to be celsius."
      },
      "unit": {
        "type": "string",
        "enum": ["celsius", "fahrenheit"],
        "default": "celsius",
        "description": "The unit of temperature."
      },
      "fanSpeed": {
        "type": "number",
        "default": 50,
        "description": "The fan speed to set from 0 to 100."
      },
      "mode": {
        "type": "string",
        "enum": ["auto", "cool", "heat", "defrost"],
        "default": "auto",
        "description": "The climate mode to set."
      }
    }
  },
  "check_tire_pressure": {
    "description": "Checks the tire pressure of the vehicle."
  },
  "displayCarStatus": {
    "description": "Displays the status of the vehicle based on the provided display option.",
    "parameters": {
      "option": {
        "type": "string",
        "enum": ["fuel", "battery", "doors", "climate", "headlights", "parkingBrake", "brakePedal", "engine"],
        "description": "The option to display."
      }
    }
  },
  "display_log": {
    "description": "Displays the log messages.",
    "parameters": {
      "messages": {
        "type": "array",
        "items": { "type": "string" },
        "description": "The list of messages to display."
      }
    }
  },
  "estimate_distance": {
    "description": "Estimates the distance between two cities.",
    "parameters": {
      "cityA": {
        "type": "string",
        "description": "The zipcode of the first city."
      },
      "cityB": {
        "type": "string",
        "description": "The zipcode of the second city."
      }
    }
  },
  "estimate_drive_feasibility_by_mileage": {
    "description": "Estimates the mileage of the vehicle given the distance needed to drive.",
    "parameters": {
      "distance": {
        "type": "number",
        "description": "The distance to travel in miles."
      }
    }
  },
  "find_nearest_tire_shop": {
    "description": "Finds the nearest tire shop."
  },
  "gallon_to_liter": {
    "description": "Converts the gallon to liter.",
    "parameters": {
      "gallon": {
        "type": "number",
        "description": "The amount of gallon to convert."
      }
    }
  },
  "get_current_speed": {
    "description": "Gets the current speed of the vehicle."
  },
  "get_outside_temperature_from_google": {
    "description": "Gets the outside temperature."
  },
  "get_outside_temperature_from_weather_com": {
    "description": "Gets the outside temperature."
  },
  "get_zipcode_based_on_city": {
    "description": "Gets the zipcode based on the city.",
    "parameters": {
      "city": {
        "type": "string",
        "description": "The name of the city."
      }
    }
  },
  "liter_to_gallon": {
    "description": "Converts the liter to gallon.",
    "parameters": {
      "liter": {
        "type": "number",
        "description": "The amount of liter to convert."
      }
    }
  },
  "lockDoors": {
    "description": "Locks the doors of the vehicle.",
    "parameters": {
      "unlock": {
        "type": "boolean",
        "description": "True if the doors are to be unlocked, False otherwise."
      },
      "door": {
        "type": "array",
        "items": { "type": "string", "enum": ["driver", "passenger", "rear_left", "rear_right"] },
        "description": "The list of doors to lock or unlock."
      }
    }
  },
  "pressBrakePedal": {
    "description": "Presses the brake pedal based on pedal position. The brake pedal will be kept pressed until released.",
    "parameters": {
      "pedalPosition": {
        "type": "number",
        "description": "Position of the brake pedal, between 0 (not pressed) and 1 (fully pressed)."
      }
    }
  },
  "releaseBrakePedal": {
    "description": "Releases the brake pedal of the vehicle."
  },
  "setCruiseControl": {
    "description": "Sets the cruise control of the vehicle.",
    "parameters": {
      "speed": {
        "type": "number",
        "description": "The speed to set in m/h. The speed should be between 0 and 120 and a multiple of 5."
      },
      "activate": {
        "type": "boolean",
        "description": "True to activate the cruise control, False to deactivate."
      },
      "distanceToNextVehicle": {
        "type": "number",
        "description": "The distance to the next vehicle in meters."
      }
    }
  },
  "setHeadlights": {
    "description": "Sets the headlights of the vehicle.",
    "parameters": {
      "mode": {
        "type": "string",
        "enum": ["on", "off", "auto"],
        "description": "The mode of the headlights."
      }
    }
  },
  "set_navigation": {
    "description": "Navigates to the destination.",
    "parameters": {
      "destination": {
        "type": "string",
        "description": "The destination to navigate in the format of street, city, state."
      }
    }
  },
  "startEngine": {
    "description": "Starts the engine of the vehicle.",
    "parameters": {
      "ignitionMode": {
        "type": "string",
        "enum": ["START", "STOP"],
        "description": "The ignition mode of the vehicle."
      }
    }
  },
  "fillFuelTank": {
    "description": "Fills the fuel tank of the vehicle. The fuel tank can hold up to 50 gallons.",
    "parameters": {
      "fuelAmount": {
        "type": "number",
        "description": "The amount of fuel to fill in gallons; this is the additional fuel to add to the tank."
      }
    }
  }
}
```

如果您想使用任何特定功能，請告訴我！
